package org.brightstats.desktop;
import java.nio.file.*;import java.util.*;import com.google.gson.*;import javafx.application.*;import javafx.scene.*;import javafx.scene.canvas.*;import javafx.scene.control.*;import javafx.scene.input.*;import javafx.scene.paint.Color;import javafx.stage.Stage;import org.brightstats.data.UserPreferences;
public final class CanvasUpgradeChecks extends Application {
 static Throwable failure;static int checks;static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 public void start(Stage stage){try{
  Path out=Path.of(getParameters().getRaw().getFirst());Files.createDirectories(out);var nodes=List.of(new ModelDiagramGraphics.Node("Long α <source> construct",3,"A",150,180,true),new ModelDiagramGraphics.Node("Outcome",4,"A",600,380,false));var edges=List.of(new ModelDiagramGraphics.Edge(0,1,-.375));Canvas canvas=new Canvas(1500,1000);Runnable paint=()->ModelDiagramGraphics.draw(canvas,nodes,edges,ModelDiagramGraphics.palette(UiAppearance.theme(),UiAppearance.current().accent()),UiAppearance.current().showGrid());canvas.getProperties().put("brightstats.redraw",paint);ModelViewport viewport=new ModelViewport(canvas,paint,()->{});List<javafx.geometry.Bounds> selections=new ArrayList<>();viewport.hooks((x,y)->false,selections::add,(g,s)->{});viewport.geometry(nodes.stream().map(n->new ModelViewport.Point(n.x(),n.y(),n.name(),n.selected())).toList(),List.of(new ModelViewport.Edge(0,1)));UiAppearance.install(UserPreferences.defaults());stage.setScene(new Scene(viewport,1000,700));stage.show();viewport.applyCss();viewport.layout();paint.run();
  viewport.zoom(99);require(viewport.zoom()==2.5,"Zoom upper bound");viewport.zoom(.01);require(viewport.zoom()==.25,"Zoom lower bound");((Slider)viewport.lookup(".slider")).setValue(.8);require(Math.abs(viewport.zoom()-.8)<1e-12,"Visible zoom slider updates the world transform");viewport.zoom(1);mouse(canvas,MouseEvent.MOUSE_PRESSED,20,20,true,true);mouse(canvas,MouseEvent.MOUSE_DRAGGED,120,130,true,true);mouse(canvas,MouseEvent.MOUSE_RELEASED,120,130,true,false);require(selections.size()==1&&selections.getFirst().contains(70,70)&&Math.abs(selections.getFirst().getWidth()-100)<.01&&Math.abs(selections.getFirst().getHeight()-110)<.01,"Actual shift-marquee events select world coordinates: "+selections);viewport.fit();require(viewport.zoom()>=.25&&viewport.zoom()<=2.5,"Fit model uses bounded zoom");require(nodes.getFirst().x()==150&&nodes.getLast().y()==380,"Navigation never mutates logical model positions");
  var curve=ModelDiagramGraphics.curve(nodes.getFirst(),nodes.getLast());require(ModelDiagramGraphics.hit(curve.sx(),curve.sy(),150,180)&&ModelDiagramGraphics.hit(curve.tx(),curve.ty(),600,380),"Curved-link endpoints meet the same rounded geometry used for hit testing");require(!ModelDiagramGraphics.hit(150+76,180+48,150,180)&&ModelDiagramGraphics.hit(150+75,180,150,180),"Rounded corners do not expose invisible hit regions");
  for(var theme:List.of(UserPreferences.Theme.LIGHT,UserPreferences.Theme.DARK,UserPreferences.Theme.HIGH_CONTRAST))for(var accent:UserPreferences.Accent.values()){var prefs=new UserPreferences(theme,UserPreferences.Language.ENGLISH,"en-US",6,13,100,8,5000000,UserPreferences.Motion.FULL,accent,UserPreferences.Density.COMFORTABLE);UiAppearance.install(prefs);var palette=ModelDiagramGraphics.palette(theme,accent);require(contrast(palette.text(),palette.card())>=4.5&&contrast(palette.muted(),palette.card())>=4.5,"Canvas text contrast in "+theme+" "+accent);require(contrast(palette.border(),palette.card())>=3,"Canvas boundary contrast in "+theme+" "+accent);Path png=out.resolve(theme.name().toLowerCase()+"-"+accent.name().toLowerCase()+".png");GraphicExport.png(png,canvas,.5);var image=javax.imageio.ImageIO.read(png.toFile());int rgb=image.getRGB(0,0)&0xffffff;require(rgb==(int)Long.parseLong(palette.background().substring(1),16),"Live theme redraw reaches the actual canvas pixels");}
  List<ModelDiagramGraphics.Node> dense=new ArrayList<>();double[][] coordinates={{115,120},{115,240},{115,360},{115,480},{355,200},{355,400},{595,300},{835,300}};for(int i=0;i<coordinates.length;i++)dense.add(new ModelDiagramGraphics.Node("C"+i,3,"A",coordinates[i][0],coordinates[i][1],false));int[][] connections={{0,4},{1,4},{1,5},{1,6},{2,4},{2,5},{3,4},{3,5},{4,6},{5,6},{5,7},{6,7}};List<ModelDiagramGraphics.Edge> denseEdges=new ArrayList<>();for(var pair:connections)denseEdges.add(new ModelDiagramGraphics.Edge(pair[0],pair[1],.123));var badges=ModelDiagramGraphics.badges(dense,denseEdges,1500,1000);require(badges.size()==12,"Every finite path estimate retains an annotation");List<ModelDiagramGraphics.Badge> annotation=new ArrayList<>(badges.values());for(int i=0;i<annotation.size();i++)for(int j=0;j<i;j++){var a=annotation.get(i);var b=annotation.get(j);double overlapX=Math.min(a.x()+a.width()/2,b.x()+b.width()/2)-Math.max(a.x()-a.width()/2,b.x()-b.width()/2),overlapY=Math.min(a.y()+9,b.y()+9)-Math.max(a.y()-15,b.y()-15);require(overlapX<=0||overlapY<=0,"Dense path coefficient badges do not overlap");}
  var source=new JsonObject();source.add("blocks",new Gson().toJsonTree(nodes));source.add("edges",new Gson().toJsonTree(edges));String svg=ModelDiagramGraphics.svg(1500,1000,nodes,edges,ModelDiagramGraphics.palette(UserPreferences.Theme.DARK,UserPreferences.Accent.OCEAN),true,source,"Diagram α <export>");Files.writeString(out.resolve("modern-diagram.svg"),svg);var factory=javax.xml.parsers.DocumentBuilderFactory.newInstance();factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);var xml=factory.newDocumentBuilder().parse(new java.io.ByteArrayInputStream(svg.getBytes(java.nio.charset.StandardCharsets.UTF_8)));require(xml.getElementsByTagName("polygon").getLength()==1&&xml.getElementsByTagName("image").getLength()==0,"Vector arrows contain no raster substitution");require(JsonParser.parseString(xml.getElementsByTagName("metadata").item(0).getTextContent()).getAsJsonObject().getAsJsonObject("graph").equals(source),"Full Unicode names and source geometry survive export");
  for(var theme:List.of(UserPreferences.Theme.LIGHT,UserPreferences.Theme.DARK)){UiAppearance.install(new UserPreferences(theme,UserPreferences.Language.ENGLISH,"en-US",6,13,100,8,5000000));viewport.applyCss();viewport.layout();GraphicExport.png(out.resolve("model-workspace-"+theme.name().toLowerCase()+".png"),viewport,1);}
  var motion=new ModelMotion(canvas,paint);Map<Integer,double[]> from=Map.of(0,new double[]{20,20}),to=Map.of(0,new double[]{150,180});motion.arrange(from,to);if(UiAppearance.effectiveMotion()==UserPreferences.Motion.FULL)require(!motion.positions().isEmpty(),"Full mode starts presentation interpolation");else require(motion.positions().isEmpty(),"Device reduced motion suppresses interpolation");var current=UiAppearance.current();UiAppearance.install(new UserPreferences(current.theme(),current.language(),current.numberLocale(),current.fractionDigits(),current.fontSize(),current.historyStates(),current.historyMiB(),current.maximumDataCells(),UserPreferences.Motion.OFF,current.accent(),current.density()));require(motion.positions().isEmpty(),"Changing motion preference settles an active layout animation");motion.arrange(from,to);require(motion.positions().isEmpty()&&to.get(0)[0]==150,"Off mode is immediate and logical targets stay unchanged");
  var custom=current.display(UserPreferences.Layout.PRESENTATION,UserPreferences.ChartPreset.PAPER,false,true);custom.save(out.resolve("preferences.json"));require(UserPreferences.load(out.resolve("preferences.json")).preferences().equals(custom),"Layout chart style and grid preferences persist");var legacy=JsonParser.parseString(Files.readString(out.resolve("preferences.json"))).getAsJsonObject();var fields=legacy.getAsJsonObject("preferences");for(String name:List.of("layout","chartPreset","showGrid","snapToGrid"))fields.remove(name);Files.writeString(out.resolve("legacy.json"),legacy.toString());var migrated=UserPreferences.load(out.resolve("legacy.json")).preferences();require(migrated.layout()==UserPreferences.Layout.BALANCED&&migrated.chartPreset()==UserPreferences.ChartPreset.STUDIO&&migrated.showGrid()&&!migrated.snapToGrid(),"Older preferences receive stable presentation defaults");
  JsonObject receipt=new JsonObject();receipt.addProperty("state","passed");receipt.addProperty("checks",checks);receipt.addProperty("palette_exports",12);receipt.addProperty("source_positions_unchanged",true);Files.writeString(out.resolve("receipt.json"),receipt.toString());System.out.println(receipt);
 }catch(Throwable problem){failure=problem;problem.printStackTrace();}finally{stage.close();Platform.exit();}}
 static void mouse(Node node,javafx.event.EventType<MouseEvent> type,double x,double y,boolean shift,boolean down){javafx.event.Event.fireEvent(node,new MouseEvent(node,node,type,node.localToScene(x,y).getX(),node.localToScene(x,y).getY(),node.localToScreen(x,y).getX(),node.localToScreen(x,y).getY(),MouseButton.PRIMARY,1,shift,false,false,false,down,false,false,false,false,true,new PickResult(node,new javafx.geometry.Point3D(x,y,0),0)));}
 static double contrast(String a,String b){double x=luminance(Color.web(a)),y=luminance(Color.web(b));return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
 static double luminance(Color color){return .2126*linear(color.getRed())+.7152*linear(color.getGreen())+.0722*linear(color.getBlue());}static double linear(double v){return v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4);}
 public static void main(String[] args){launch(args);if(failure!=null)System.exit(1);}
}
